private void validateVarOrAssignmentTarget(Node n) {
    if (n.getType() == Token.VAR) {
      // Only one NAME can be declared for FOR-IN expressions.
      this.validateChildCount(n, 1);
      validateVar(n);
    } else {
      validateAssignmentTarget(n);
    }
  }

